package com.sora.splineroads.world;import java.util.*;import com.sora.splineroads.core.RoadGeometry.*;public class RoadIndex {public final Map<UUID,Built> roads=new LinkedHashMap<>();private long revision;public long revision(){return revision;}public void put(Built b){roads.put(b.record.id(),b);revision++;}public static boolean overlapXZ(Mesh a,Mesh b,double margin){return a.min().x()<=b.max().x()+margin&&a.max().x()+margin>=b.min().x()&&a.min().z()<=b.max().z()+margin&&a.max().z()+margin>=b.min().z();}public static class Built {public final RoadRecord record;public final Mesh mesh;public Built(RoadRecord r){record=r;mesh=r.mesh();}public static Built loading(RoadRecord r){return new Built(r);}}}